}
res = await asyncio.gather(*jobs.values(), return_exceptions=True)
return {k: (r if isinstance(r,str) else str(r))[:1800] for k,r in zip(jobs.keys(),res)}

import asyncio
jobs = {
 "processenv_all": pi.grep(pattern="process\\.env", path="extensions"),
 "anyprocess": pi.grep(pattern="process", path="extensions"),
 "types_node": pi.bash(command="ls -d node_modules/@types/node node_modules/@types 2>&1 | head -20; ls node_modules/@types 2>/dev/null | head -30"),
}
res = await asyncio.gather(*jobs.values(), return_exceptions=True)
out = {}
for k,r in zip(jobs.keys(),res):
    out[k] = (r if isinstance(r,str) else str(r))[:2000]
return out

